C 동적 메모리 (malloc · free).code:
#include <stdio.h>
#include <stdlib.h>

int main() {
    int *p = (int*)malloc(sizeof(int) * 5);
    int i, sum = 0;
    for (i = 0; i < 5; i++)
        p[i] = (i + 1) * 10;
    for (i = 0; i < 5; i++)
        sum += *(p + i);
    printf("%d %d\n", p[2], sum);
    free(p);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main() {
    int *a = (int*)calloc(3, sizeof(int));
    int i;
    for (i = 0; i < 3; i++)
        printf("%d ", a[i]);
    a[1] = 7;
    printf("\n%d\n", a[0] + a[1] + a[2]);
    free(a);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

struct node {
    int data;
    struct node *next;
};

int main() {
    struct node *head = (struct node*)malloc(sizeof(struct node));
    struct node *n2 = (struct node*)malloc(sizeof(struct node));
    head->data = 1;
    head->next = n2;
    n2->data = 2;
    n2->next = NULL;
    struct node *p = head;
    while (p != NULL) {
        printf("%d ", p->data);
        p = p->next;
    }
    free(head);
    free(n2);
    return 0;
}

